select provider_game_id id,player_stats_captured_at at,player_stats->'data'->0->'game' game,(select jsonb_agg(jsonb_build_array(x#>>'{player,id}',x#>>'{team,id}',x->>'min',x->'pts',x->'reb',x->'ast',x->'fg3m',x->'stl',x->'blk',x->'turnover',x->>'comment')) from jsonb_array_elements(player_stats->'data') x) players from nba_game_context_v2 where player_stats->'data'->0->'game'->>'status'='Final' order by provider_game_id
